# Golden values for phn-epi hypothesis.rs (R defaults).
# Run: Rscript hypothesis.R > ../hypothesis.json  (then hypothesis_scipy.py adds Brown-Forsythe)
suppressPackageStartupMessages(library(jsonlite))
set.seed(42)
x <- round(rnorm(18, 120, 15), 1); y <- round(rnorm(22, 112, 22), 1)
xs <- c(1.2, 3.4, 2.2, 5.1, 4.4, 0.7, 2.9); ys <- c(6.1, 3.9, 7.2, 5.5, 8.4, 4.8, 6.6, 9.1)
xt <- c(3, 5, 5, 7, 8, 8, 8, 10, 12); yt <- c(6, 9, 9, 11, 13, 15, 15, 16)
pre <- c(142, 138, 150, 160, 155, 147, 139, 152, 165, 148); post <- c(135, 136, 141, 152, 149, 142, 140, 146, 155, 144)
pre2 <- c(5, 3, 6, 6, 4, 7, 5, 8, 6, 5, 7, 4); post2 <- c(4, 3, 5, 3, 4, 5, 2, 6, 5, 4, 6, 4)
g1 <- c(23, 25, 21, 27, 24, 26, 22); g2 <- c(28, 30, 27, 33, 29, 31); g3 <- c(22, 35, 18, 40, 26, 31, 19, 28)
tab <- matrix(c(20, 15, 12, 8, 30, 25, 9, 14, 21), nrow = 3, byrow = TRUE)
cx <- c(1.1, 2.3, 2.9, 4.2, 5.0, 5.8, 7.1, 8.3, 9.0, 10.4, 11.2, 12.5)
cy <- c(2.0, 2.9, 3.1, 5.2, 4.8, 6.9, 7.2, 8.0, 9.9, 9.7, 12.1, 12.6)
sw <- list(x, y, xs, ys, c(1, 2, 3), c(2.1, 3.4, 1.9, 5.6), c(10, 12, 11, 13, 50, 12, 11, 14, 10, 12),
           round(rexp(40, 0.2), 2))
tt <- function(r) list(stat = unname(r$statistic), p = r$p.value,
                       df = if (!is.null(r$parameter)) unname(r$parameter[1]) else NULL,
                       df2 = if (length(r$parameter) > 1) unname(r$parameter[2]) else NULL,
                       lower = if (!is.null(r$conf.int)) r$conf.int[1] else NULL,
                       upper = if (!is.null(r$conf.int)) r$conf.int[2] else NULL,
                       estimate = if (!is.null(r$estimate)) unname(r$estimate[1] - if (length(r$estimate) > 1) r$estimate[2] else 0) else NULL)
out <- list(
  data = list(x = x, y = y, xs = xs, ys = ys, xt = xt, yt = yt, pre = pre, post = post, pre2 = pre2, post2 = post2,
              g1 = g1, g2 = g2, g3 = g3, tab = tab, cx = cx, cy = cy, sw = sw),
  welch = tt(t.test(x, y)), student = tt(t.test(x, y, var.equal = TRUE)), paired = tt(t.test(pre, post, paired = TRUE)),
  mw_exact = tt(wilcox.test(xs, ys)), mw_ties = tt(suppressWarnings(wilcox.test(xt, yt))),
  sr_exact = tt(wilcox.test(pre, post, paired = TRUE)), sr_ties = tt(suppressWarnings(wilcox.test(pre2, post2, paired = TRUE))),
  anova = tt(oneway.test(c(g1, g2, g3) ~ factor(rep(1:3, c(7, 6, 8))), var.equal = TRUE)),
  welch_anova = tt(oneway.test(c(g1, g2, g3) ~ factor(rep(1:3, c(7, 6, 8))))),
  kruskal = tt(kruskal.test(list(g1, g2, g3))), kruskal_ties = tt(kruskal.test(list(xt, yt, c(5, 8, 9, 9, 12)))),
  chisq = tt(chisq.test(tab)),
  pearson = tt(cor.test(cx, cy)), spearman = tt(suppressWarnings(cor.test(cx, cy, method = "spearman", exact = FALSE))),
  shapiro = lapply(sw, function(v) { r <- shapiro.test(v); list(w = unname(r$statistic), p = r$p.value) }))
out$pearson$estimate <- unname(cor(cx, cy)); out$spearman$estimate <- unname(cor(cx, cy, method = "spearman"))
cat(toJSON(c(list(note = "Generated by tests/fixtures/generators/hypothesis.R (R t.test, wilcox.test, oneway.test, kruskal.test, chisq.test, cor.test, shapiro.test); hypothesis_scipy.py adds scipy.stats.levene(center='median').",
                  r_version = R.version.string), out), auto_unbox = TRUE, digits = NA, pretty = TRUE, matrix = "rowmajor"))
